import {registerPaymentMethodExtensionCallbacks} from '@woocommerce/blocks-registry';

const allowedGateways = yith_allowed_gateway_args.gateways;
const allGateways = yith_allowed_gateway_args.all_gateways;

const getObjectCallback = () => {
    const obj = [];
    allGateways.forEach(gateway => {
        const fund = allowedGateways.filter(allowed => allowed === gateway);
        obj[gateway] = (arg) => {
            const hasDeposit = arg.cart.cartItems.filter(item => item.id === parseInt(yith_allowed_gateway_args.deposit_product_id)).length > 0;
            if (hasDeposit.length > 0) {
                return fund.length > 0;
            } else {
                return true;
            }
        }
    });

    return obj;

}


const obj = getObjectCallback();
registerPaymentMethodExtensionCallbacks('yith-funds-allowed-gateways-for-deposit', {...obj});